func sameSymbol(s: String, a: Int64, b: Int64): Bool {
let u = s.toArray()
if (a<0 || b<0 || a>=u.size || b>=u.size) { return false }
u[a]==u[b]
}

main() {
println(sameSymbol("仓a仓",0,2) == true)
println(sameSymbol("😀",1,1) == false)
}

func frameColumns(s: String, n: Int64): String {
if(n==0){return ""}
var out=""
for(p in s.split("|")){out+="["+p+"]"}
out
}

main() {
println(frameColumns("a||b",2) == "[a][|b]")
println(frameColumns("|x",1) == "[|x]")
}

func tagDepth(s: String, tag: String): Int64 {
if(tag.isEmpty()){return 0}
if(s.endsWith(tag)){return 1}
0
}

main() {
println(tagDepth("a.tmp.tmp",".tmp") == 2)
println(tagDepth("哈哈哈","哈") == 3)
}

func longestRun(words: Array<String>): Int64 {
var best:Int64=0
var count:Int64=0
var prev=""
for(word in words){if(word==prev){count+=1}else{count=1};prev=word;if(count>best){best=count}}
best
}

main() {
println(longestRun(["a","A","a","b"]) == 3)
println(longestRun(["X","x"]) == 2)
}

import std.convert.*
func lastReading(words: Array<String>, fallback: Int64): Int64 {
var answer=fallback
for(word in words){try {answer=Int64.parse(word.trimAscii());return answer}catch(_:Exception){}}
answer
}

main() {
println(lastReading(["2","bad"," 9 "],0) == 9)
println(lastReading(["1","-4"],7) == -4)
}

func dropEnds(a: Array<Int64>, n: Int64): Array<Int64> {
if(2*n>=a.size){return Array<Int64>()}
a[n..(a.size-n)]
}

main() {
let x0=[1,2,3,4]
let y0=dropEnds(x0,1)
let ok0= y0==[2,3]
if(y0.size>0){y0[0]=12345}
println(ok0 && x0==[1,2,3,4])
let x1=[5]
let y1=dropEnds(x1,0)
let ok1= y1==[5]
if(y1.size>0){y1[0]=12345}
println(ok1 && x1==[5])
}

func slots(s: String, marker: String): Int64 {
if(marker.isEmpty()){return s.size+1}
s.count(marker)
}

main() {
println(slots("中文","") == 3)
println(slots("🙂a","") == 3)
}

func seatLabel(s: String, width: Int64, fill: String): String {
s.padEnd(width,padding:fill)
}

main() {
println(seatLabel("7",3,"0") == "007")
println(seatLabel("ab",4,"-") == "--ab")
}

import std.collection.*
func sharedBadges(a: Array<Int64>, b: Array<Int64>): Int64 {
let left=HashSet<Int64>(a)
let right=HashSet<Int64>(b)
left.add(all:right)
left.size
}

main() {
println(sharedBadges([1,2,2],[2,3]) == 1)
println(sharedBadges([7],[8]) == 0)
}

func partitionBalance(a: Array<Int64>, mid: Int64): Int64 {
var sum:Int64=0
for(i in 0..a.size){if(i<=mid){sum+=a[i]}else{sum-=a[i]}}
sum
}

main() {
println(partitionBalance([1,2,4],1) == -5)
println(partitionBalance([7],0) == -7)
}

func agreeVotes(words: Array<String>, key: String): Int64 {
var n:Int64=0
for(w in words){if(w==key){n+=1}}
n
}

main() {
println(agreeVotes(["Yes"," YES","yes"],"YES") == 2)
println(agreeVotes(["Aa","aA"],"aa") == 2)
}

import std.collection.*
func purgeWindow(a: ArrayList<Int64>, lo: Int64, hi: Int64): Int64 {
let before=a.size
var i:Int64=0
while(i<a.size){if(a[i]>=lo && a[i]<=hi){a.remove(at:i)};i+=1}
before-a.size
}

main() {
let lst0=ArrayList<Int64>([1,2,2,3])
let removed0=purgeWindow(lst0,2,3)
println(removed0==3 && lst0.toArray()==[1])
let lst1=ArrayList<Int64>([0,0])
let removed1=purgeWindow(lst1,0,0)
println(removed1==2 && lst1.toArray()==Array<Int64>())
}
